-- Landmine moves, the same rows as drizzle/0058_landmine_rows.sql.
-- Appended to seed.sql after libraryStrength.sql.
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-landmine-press', 'Landmine Press', 'strength', 'shoulders,triceps,core', 'landmine', 'Half-kneeling, the down knee on the same side as the pressing arm, front hip and knee near 90 degrees. Squeeze the down-side glute, ribs down, press the bar end up and out, reach at the top. Chin tucked.', 'https://www.youtube.com/watch?v=_ArzG9qz-yM', 1793000000);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-lm-press-standing', 'Standing Landmine Press', 'strength', 'shoulders,triceps,core', 'landmine', 'Split stance, the same-side leg back. Bar end at the shoulder. Ribs down, press up and out, reach at the top. The legs help you balance.', 'https://www.youtube.com/watch?v=Sjb5meztfSE', 1793000000);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-lm-reverse-lunge', 'Landmine Reverse Lunge', 'strength', 'quads,glutes,core', 'landmine', 'Hold the bar end at the chest with both hands and lean slightly into it. Step back slowly, front shin near vertical, drive up through the front foot.', 'https://www.youtube.com/watch?v=s70b_r3heMs', 1793000000);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-lm-sl-rdl', 'Landmine Single-Leg RDL', 'strength', 'hamstrings,glutes,core', 'landmine', 'Bar beside you, hold it with the near hand. Hips square to the floor, soft standing knee, back leg long, reach the bar down the shin.', 'https://www.youtube.com/watch?v=GFEdRNDY4jI', 1793000000);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-lm-rdl', 'Landmine RDL', 'strength', 'hamstrings,glutes', 'landmine', 'Face the bar end and hold it with both hands. Soft knees, push the hips back, shins still, the bar slides down the thighs. Stand by squeezing the glutes.', 'https://www.youtube.com/watch?v=-La5ehYegb0', 1793000000);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-lm-lateral-lunge', 'Landmine Lateral Lunge', 'strength', 'adductors,glutes,quads', 'landmine', 'Hold the bar end at the chest. Step wide to one side, sit back into that hip, the other leg straight. Toes forward, chest up.', 'https://www.youtube.com/watch?v=rAxkgCNj1OA', 1793000000);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-lm-rainbow', 'Landmine Rainbow', 'core', 'obliques,core,shoulders', 'landmine', 'Stand square, arms long, bar end at head height. Lower it in a slow arc to one hip, then over to the other. Hips and ribs face front.', 'https://www.youtube.com/watch?v=j6dijH9KnWY', 1793000000);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-lm-punch', 'Landmine Punch', 'strength', 'shoulders,chest,core,hips', 'landmine', 'Split stance, left foot forward, bar end at the right shoulder. Pivot the back foot, turn the rear hip, punch the bar up and out. The hip turns first, the arm finishes.', 'https://www.youtube.com/watch?v=Xn-MdOa5i7M', 1793000000);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-lm-rotational-press', 'Landmine Rotational Press', 'strength', 'obliques,hips,shoulders', 'landmine', 'Arms long, bar end at chest height. Turn the feet and hips with the bar to one side, then drive it back to the middle fast.', 'https://www.youtube.com/watch?v=ONDeomDVlbE', 1793000000);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-lm-push-press', 'Landmine Push Press', 'strength', 'shoulders,triceps,quads', 'landmine', 'Bar end at the shoulder. A short dip of the knees, then drive with the legs and press the bar up and out.', 'https://www.youtube.com/watch?v=6aVFcQmSrVc', 1793000000);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-lm-squat', 'Landmine Squat', 'strength', 'quads,glutes', 'landmine', 'Hold the bar end at the chest with both hands, lean into it, feet a bit ahead of the hips. Chest up, sit between the hips, knees out.', 'https://www.youtube.com/watch?v=hJ6XnlQ3yBU', 1793000000);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-lm-meadows-row', 'Meadows Row', 'strength', 'back,biceps,grip', 'landmine', 'Stand side-on to the bar end, staggered stance, hold the sleeve overhand. Hinge, pull the elbow up and back to the hip.', 'https://www.youtube.com/watch?v=G-jU1aPVhnY', 1793000000);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-lm-rotation', 'Landmine Rotation', 'core', 'obliques,core', 'landmine', 'Feet hip-width, arms long, bar end at chest height. Turn the shoulders to bring the bar to the outside of one thigh, back to centre, then the other side. Feet, knees and hips still.', 'https://www.youtube.com/watch?v=DiVMWoLCTLo', 1793000000);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-lm-thruster', 'Landmine Thruster', 'strength', 'quads,glutes,shoulders', 'landmine', 'A landmine squat straight into a push press: sit down holding the bar end at the chest, stand fast and press it up and out.', 'https://www.youtube.com/watch?v=9f0TrDK9hFY', 1793000000);
INSERT OR IGNORE INTO exercises (id, name, category, muscle_groups, equipment, form_cues, form_video_url, created_at) VALUES ('ex-lm-calf-raise', 'Landmine Calf Raise', 'strength', 'calves,achilles', 'landmine', 'Bar end at the chest or on the shoulder, balls of the feet on a plate. Rise as high as you can, lower for 2-3 seconds.', 'https://www.youtube.com/watch?v=Th_RhHeEjbM', 1793000000);
UPDATE exercises SET name = 'Landmine Press', category = 'strength', muscle_groups = 'shoulders,triceps,core', equipment = 'landmine', form_cues = 'Half-kneeling, the down knee on the same side as the pressing arm, front hip and knee near 90 degrees. Squeeze the down-side glute, ribs down, press the bar end up and out, reach at the top. Chin tucked.', tips = 'Don''t shrug to start or lean back. | Elbow stays close, not flared wide. | Lower under control.', coach_hint = 'The coach''s press while the shoulders and back rebuild: shoulder-kind, and the trunk resists twisting.', form_video_url = 'https://www.youtube.com/watch?v=_ArzG9qz-yM', video_start_sec = NULL, video_source = 'Eric Cressey', video_title = 'Half-Kneeling 1-arm Landmine Press', video_length = '1:18', video_status = 'live', alt_video_url = 'https://www.youtube.com/watch?v=nwrx4X5UTmE', alt_video_source = 'Horton Barbell', alt_video_status = 'live', merged_into = NULL WHERE id = 'ex-landmine-press';
UPDATE exercises SET name = 'Standing Landmine Press', category = 'strength', muscle_groups = 'shoulders,triceps,core', equipment = 'landmine', form_cues = 'Split stance, the same-side leg back. Bar end at the shoulder. Ribs down, press up and out, reach at the top. The legs help you balance.', tips = 'Same cues as half-kneeling. | Press straight out, not across the body.', coach_hint = 'The next step from the half-kneeling press.', form_video_url = 'https://www.youtube.com/watch?v=Sjb5meztfSE', video_start_sec = NULL, video_source = 'Coach Joe Drake', video_title = 'Single-Arm Landmine Press [technique breakdown]', video_length = '2:55', video_status = 'live', alt_video_url = 'https://www.youtube.com/watch?v=S76L-On4Zas', alt_video_source = 'E3 Rehab', alt_video_status = 'live', merged_into = NULL WHERE id = 'ex-lm-press-standing';
UPDATE exercises SET name = 'Landmine Reverse Lunge', category = 'strength', muscle_groups = 'quads,glutes,core', equipment = 'landmine', form_cues = 'Hold the bar end at the chest with both hands and lean slightly into it. Step back slowly, front shin near vertical, drive up through the front foot.', tips = 'Take a long enough step. | Knee tracks over the foot, not in. | Don''t twist toward the bar.', coach_hint = 'Single-leg strength for running and kicking, easy to balance and kind to the knees.', form_video_url = 'https://www.youtube.com/watch?v=s70b_r3heMs', video_start_sec = NULL, video_source = 'Bret Contreras', video_title = 'Ben Bruno Teaches the Landmine Reverse Lunge', video_length = '5:33', video_status = 'live', alt_video_url = 'https://www.youtube.com/watch?v=U0eEJIOkkE4', alt_video_source = 'E3 Rehab', alt_video_status = 'live', merged_into = NULL WHERE id = 'ex-lm-reverse-lunge';
UPDATE exercises SET name = 'Landmine Single-Leg RDL', category = 'strength', muscle_groups = 'hamstrings,glutes,core', equipment = 'landmine', form_cues = 'Bar beside you, hold it with the near hand. Hips square to the floor, soft standing knee, back leg long, reach the bar down the shin.', tips = 'Don''t let the hip open toward the ceiling. | Standing knee soft, never locked.', coach_hint = 'A runner''s single-leg hinge the bar helps you balance.', form_video_url = 'https://www.youtube.com/watch?v=GFEdRNDY4jI', video_start_sec = NULL, video_source = 'Bret Contreras', video_title = 'Ben Bruno Teaches the Landmine Single Leg RDL', video_length = '5:09', video_status = 'live', alt_video_url = 'https://www.youtube.com/watch?v=VNqNNcgx2Hg', alt_video_source = 'E3 Rehab', alt_video_status = 'live', merged_into = NULL WHERE id = 'ex-lm-sl-rdl';
UPDATE exercises SET name = 'Landmine RDL', category = 'strength', muscle_groups = 'hamstrings,glutes', equipment = 'landmine', form_cues = 'Face the bar end and hold it with both hands. Soft knees, push the hips back, shins still, the bar slides down the thighs. Stand by squeezing the glutes.', tips = 'Don''t squat it. | Stop at mid-shin, never round to reach low.', coach_hint = 'A light hinge in the warm-up, and a back-friendly hinge on a sore-back day.', form_video_url = 'https://www.youtube.com/watch?v=-La5ehYegb0', video_start_sec = NULL, video_source = 'Alec Blenis', video_title = 'Landmine RDL', video_length = '5:27', video_status = 'live', alt_video_url = 'https://www.youtube.com/watch?v=H4pjKaDO7AU', alt_video_source = 'E3 Rehab', alt_video_status = 'live', merged_into = NULL WHERE id = 'ex-lm-rdl';
UPDATE exercises SET name = 'Landmine Lateral Lunge', category = 'strength', muscle_groups = 'adductors,glutes,quads', equipment = 'landmine', form_cues = 'Hold the bar end at the chest. Step wide to one side, sit back into that hip, the other leg straight. Toes forward, chest up.', tips = 'Knee tracks over the toes, not in. | Push back to the middle.', coach_hint = 'Groin and hips for kicks and side steps.', form_video_url = 'https://www.youtube.com/watch?v=rAxkgCNj1OA', video_start_sec = NULL, video_source = 'E3 Rehab', video_title = 'Landmine Lateral Lunge', video_length = '0:13', video_status = 'live', alt_video_url = 'https://www.youtube.com/watch?v=SUPnlm9iFF4', alt_video_source = 'Power Athlete', alt_video_status = 'live', merged_into = NULL WHERE id = 'ex-lm-lateral-lunge';
UPDATE exercises SET name = 'Landmine Rainbow', category = 'core', muscle_groups = 'obliques,core,shoulders', equipment = 'landmine', form_cues = 'Stand square, arms long, bar end at head height. Lower it in a slow arc to one hip, then over to the other. Hips and ribs face front.', tips = 'Small arc first, to the shoulder. | Arms long, slow, no spin.', coach_hint = 'Anti-rotation for the trunk: the hips stay put while the bar moves.', form_video_url = 'https://www.youtube.com/watch?v=j6dijH9KnWY', video_start_sec = NULL, video_source = 'Stark.Health', video_title = 'Landmine Rainbow Tutorial', video_length = '2:55', video_status = 'live', alt_video_url = 'https://www.youtube.com/watch?v=c6_FnMLPsys', alt_video_source = 'E3 Rehab', alt_video_status = 'live', merged_into = NULL WHERE id = 'ex-lm-rainbow';
UPDATE exercises SET name = 'Landmine Punch', category = 'strength', muscle_groups = 'shoulders,chest,core,hips', equipment = 'landmine', form_cues = 'Split stance, left foot forward, bar end at the right shoulder. Pivot the back foot, turn the rear hip, punch the bar up and out. The hip turns first, the arm finishes.', tips = 'Slow and crisp first, fast later. | Every rep a single: reset, then go. | Both sides.', coach_hint = 'Punch power: the rear hip and the push through the shoulder, like the cross.', form_video_url = 'https://www.youtube.com/watch?v=Xn-MdOa5i7M', video_start_sec = NULL, video_source = 'Boxing Science', video_title = 'Landmine Punch Tutorial by Boxing Science', video_length = '8:51', video_status = 'live', alt_video_url = 'https://www.youtube.com/watch?v=NGOeukXF4yE', alt_video_source = 'Boxing Science', alt_video_status = 'live', merged_into = NULL WHERE id = 'ex-lm-punch';
UPDATE exercises SET name = 'Landmine Rotational Press', category = 'strength', muscle_groups = 'obliques,hips,shoulders', equipment = 'landmine', form_cues = 'Arms long, bar end at chest height. Turn the feet and hips with the bar to one side, then drive it back to the middle fast.', tips = 'The feet and hips turn with it. | Turn with the hips, not the lower back.', coach_hint = 'Rotational power, the fast version for kicks and hooks.', form_video_url = 'https://www.youtube.com/watch?v=ONDeomDVlbE', video_start_sec = NULL, video_source = 'IMPACT Health & Performance', video_title = 'Landmine Rotational Press', video_length = '0:38', video_status = 'live', alt_video_url = 'https://www.youtube.com/watch?v=-mtU3hc1OVE', alt_video_source = 'Littauer Strength Training', alt_video_status = 'live', merged_into = NULL WHERE id = 'ex-lm-rotational-press';
UPDATE exercises SET name = 'Landmine Push Press', category = 'strength', muscle_groups = 'shoulders,triceps,quads', equipment = 'landmine', form_cues = 'Bar end at the shoulder. A short dip of the knees, then drive with the legs and press the bar up and out.', tips = 'Short dip, fast drive. | The legs start it, the arm finishes.', coach_hint = 'Upper-body power with leg drive.', form_video_url = 'https://www.youtube.com/watch?v=6aVFcQmSrVc', video_start_sec = NULL, video_source = 'Stark.Health', video_title = 'Landmine Pushpress Tutorial', video_length = '2:01', video_status = 'live', alt_video_url = 'https://www.youtube.com/watch?v=g2Ylyd_eKpE', alt_video_source = 'Stark.Health', alt_video_status = 'live', merged_into = NULL WHERE id = 'ex-lm-push-press';
UPDATE exercises SET name = 'Landmine Squat', category = 'strength', muscle_groups = 'quads,glutes', equipment = 'landmine', form_cues = 'Hold the bar end at the chest with both hands, lean into it, feet a bit ahead of the hips. Chest up, sit between the hips, knees out.', tips = 'Only as deep as the hips allow. | Heels stay down.', coach_hint = 'A squat for back days: upright, less knee travel.', form_video_url = 'https://www.youtube.com/watch?v=hJ6XnlQ3yBU', video_start_sec = NULL, video_source = 'Bret Contreras', video_title = 'Ben Bruno Teaches the Landmine Squat', video_length = '4:53', video_status = 'live', alt_video_url = 'https://www.youtube.com/watch?v=_mfORB47xMs', alt_video_source = 'Ben Bruno', alt_video_status = 'live', merged_into = NULL WHERE id = 'ex-lm-squat';
UPDATE exercises SET name = 'Meadows Row', category = 'strength', muscle_groups = 'back,biceps,grip', equipment = 'landmine', form_cues = 'Stand side-on to the bar end, staggered stance, hold the sleeve overhand. Hinge, pull the elbow up and back to the hip.', tips = 'Hips high, chest still. | Don''t jerk the torso. | Straps are fine.', coach_hint = 'A row for variety, or when the dumbbell row bothers the low back.', form_video_url = 'https://www.youtube.com/watch?v=G-jU1aPVhnY', video_start_sec = NULL, video_source = 'mountaindog1 (John Meadows)', video_title = 'How to Meadows Row "The Right Way"', video_length = '1:55', video_status = 'live', alt_video_url = 'https://www.youtube.com/watch?v=heabDFBKKRA', alt_video_source = 'Merrick Lincoln DPT', alt_video_status = 'live', merged_into = NULL WHERE id = 'ex-lm-meadows-row';
UPDATE exercises SET name = 'Landmine Rotation', category = 'core', muscle_groups = 'obliques,core', equipment = 'landmine', form_cues = 'Feet hip-width, arms long, bar end at chest height. Turn the shoulders to bring the bar to the outside of one thigh, back to centre, then the other side. Feet, knees and hips still.', tips = 'Small arc first. | Turn the chest, not the lower back.', coach_hint = 'The stability version of rotation; the punch and the rotational press come after it.', form_video_url = 'https://www.youtube.com/watch?v=DiVMWoLCTLo', video_start_sec = NULL, video_source = 'Swift Movement Academy', video_title = 'How To Do Landmine Rotations', video_length = '1:02', video_status = 'live', alt_video_url = 'https://www.youtube.com/watch?v=hToWbsOSuOA', alt_video_source = 'Mike Boyle S&C', alt_video_status = 'live', merged_into = NULL WHERE id = 'ex-lm-rotation';
UPDATE exercises SET name = 'Landmine Thruster', category = 'strength', muscle_groups = 'quads,glutes,shoulders', equipment = 'landmine', form_cues = 'A landmine squat straight into a push press: sit down holding the bar end at the chest, stand fast and press it up and out.', tips = 'Low reps, crisp. | A power move, not a conditioning finisher.', coach_hint = 'Optional power from the squat into the press.', form_video_url = 'https://www.youtube.com/watch?v=9f0TrDK9hFY', video_start_sec = NULL, video_source = 'Jenny LaBaw', video_title = 'Landmine Thruster', video_length = '1:21', video_status = 'live', alt_video_url = 'https://www.youtube.com/watch?v=FlfhcM9isDA', alt_video_source = 'Testosterone Nation', alt_video_status = 'live', merged_into = NULL WHERE id = 'ex-lm-thruster';
UPDATE exercises SET name = 'Landmine Calf Raise', category = 'strength', muscle_groups = 'calves,achilles', equipment = 'landmine', form_cues = 'Bar end at the chest or on the shoulder, balls of the feet on a plate. Rise as high as you can, lower for 2-3 seconds.', tips = 'Full stretch at the bottom. | Slow on the way down.', coach_hint = 'A way to load the calves heavy.', form_video_url = 'https://www.youtube.com/watch?v=Th_RhHeEjbM', video_start_sec = NULL, video_source = 'Functional Bodybuilding', video_title = 'Landmine Calf Raise', video_length = '0:18', video_status = 'live', alt_video_url = 'https://www.youtube.com/watch?v=OYDAfufJRs0', alt_video_source = 'Katiedee_pt', alt_video_status = 'live', merged_into = NULL WHERE id = 'ex-lm-calf-raise';
